$('#dialog').addEventListener('close',()=>{$('#dialog-content').replaceChildren();$('#dialog').classList.remove('resource-dialog','certificate-dialog');});

// Convert supported links to in-campus viewers; never embed arbitrary HTML.
function resourceSource(value){
 let u;try{u=new URL(value);}catch{return null;}
 if(u.protocol!=='https:'||u.username||u.password)return null;
 const host=u.hostname.toLowerCase(),parts=u.pathname.split('/').filter(Boolean);
 if(['youtube.com','www.youtube.com','m.youtube.com','youtu.be','www.youtube-nocookie.com'].includes(host)){
  const id=host==='youtu.be'?parts[0]:['embed','shorts','live'].includes(parts[0])?parts[1]:u.searchParams.get('v');
  if(!/^[A-Za-z0-9_-]{11}$/.test(id||''))return null;
  return {kind:'frame',video:true,url:'https://www.youtube-nocookie.com/embed/'+id};
 }
 if(host==='drive.google.com'){
  const match=u.pathname.match(/\/file\/d\/([\w-]+)/),id=match?.[1]||u.searchParams.get('id');
  if(!/^[\w-]+$/.test(id||''))return null;
  const preview=new URL('https://drive.google.com/file/d/'+id+'/preview');
  if(u.searchParams.has('resourcekey'))preview.searchParams.set('resourcekey',u.searchParams.get('resourcekey'));
  return {kind:'frame',url:preview.href};
 }
 if(host==='docs.google.com'){
  const m=u.pathname.match(/^\/(document|spreadsheets|presentation)\/d\/(?:e\/)?([\w-]+)(\/.*)?$/);
  if(m){const published=u.pathname.includes('/d/e/');return {kind:'frame',url:u.origin+'/'+m[1]+'/d/'+(published?'e/':'')+m[2]+'/'+(published?(m[1]==='spreadsheets'?'pubhtml':m[1]==='presentation'?'embed':'pub'):'preview')};}
 }
 const ext=u.pathname.split('.').pop().toLowerCase();
 const kind=['mp4','webm','ogv'].includes(ext)?'video':['mp3','wav','ogg','m4a'].includes(ext)?'audio':['png','jpg','jpeg','gif','webp','avif'].includes(ext)?'image':ext==='pdf'?'frame':null;
 return kind?{kind,url:u.href}:null;
}
function resourceViewer(url,title){
 const source=resourceSource(url),label=esc(title||'Material del curso');
 let content='';
 if(source){const src=esc(source.url);
  if(source.kind==='video')content=`<video controls playsinline preload="metadata" aria-label="${label}" src="${src}"></video>`;
  else if(source.kind==='audio')content=`<audio controls preload="metadata" aria-label="${label}" src="${src}"></audio>`;
  else if(source.kind==='image')content=`<img loading="lazy" src="${src}" alt="${label}">`;
  else content=`<iframe class="${source.video?'video-frame':''}" src="${src}" title="${label}" loading="lazy" referrerpolicy="strict-origin-when-cross-origin" sandbox="allow-scripts allow-same-origin allow-forms allow-presentation" allow="fullscreen; encrypted-media; picture-in-picture" allowfullscreen></iframe>`;
 }
 return `<section class="resource-viewer" aria-label="Material del curso">${content||'<p>Este enlace no tiene una vista previa compatible. Para verlo aquí, utiliza un archivo de Drive, YouTube, PDF, imagen, audio o video directo.</p>'}<details><summary>${source?'¿No se muestra el material?':'Opciones del recurso'}</summary><p>El archivo debe permitir acceso a tu cuenta y visualización integrada. Algunos proveedores bloquean esta vista. Para documentos de Office, utiliza su enlace de Google Drive.</p>${safeUrl(url)!=='#'?`<a href="${safeUrl(url)}" target="_blank" rel="noopener noreferrer">Abrir original si lo necesitas ↗</a>`:''}</details></section>`;
}


function coverImage(value,label){const src=String(value||'');if(!/^https:\/\//i.test(src)&&!/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/]+={0,2}$/.test(src))return '';return `<img class="cover-image" src="${esc(src)}" alt="${esc(label||'Portada')}" loading="lazy" decoding="async" referrerpolicy="no-referrer">`;}
function schoolCard(s){const n=catalog.courses.filter(c=>c.schoolId===s.id).length;return `<button class="school ${s.image?'school-with-image':''}" data-action="school" data-school="${esc(s.name)}">${s.image?coverImage(s.image,s.name):`<span class="school-symbol">${esc(s.icon||'◇')}</span>`}<strong>${esc(s.name)}</strong>${s.description?`<span class="school-description">${esc(s.description)}</span>`:''}<small>${n} ${n===1?'curso':'cursos'}</small></button>`;}
function schoolsAdmin(){return `<div class="section-head"><div><h2>Escuelas de formación</h2><p class="muted">Organiza las categorías, sus portadas y el orden en el campus.</p></div>${btn('+ Crear escuela','new-school')}</div>${table(['Escuela','Cursos','Orden','Acciones'],(admin.schools||[]).map(s=>[esc(s.name),admin.courses.filter(c=>c.schoolId===s.id).length,s.order,btn('Editar','edit-school',`data-id="${esc(s.id)}"`,'secondary small')+' '+btn('Eliminar','delete-school',`data-id="${esc(s.id)}" data-updated="${esc(s.updated)}"`,'secondary small')]))}<p class="muted small">Antes de eliminar una escuela con cursos, asigna esos cursos a otra escuela desde Cursos → Editar. Se conservan sus avances y certificados.</p>`;}
function imageEditor(value){return `<div class="image-editor"><label>Imagen de portada</label><div class="image-preview">${coverImage(value,'Vista previa de portada')||'Sin imagen'}</div><input type="hidden" name="image" value="${esc(value||'')}"><label>Subir desde tu equipo<input class="image-file" type="file" accept="image/jpeg,image/png,image/webp"></label><p class="muted small">JPG, PNG o WebP, máximo 8 MB. Se optimiza como miniatura antes de guardar. La portada será visible públicamente.</p><label>O usar un enlace directo HTTPS<input class="image-url" type="url" value="${esc(/^https:\/\//.test(value||'')?value:'')}" placeholder="https://ejemplo.com/portada.jpg"></label><div class="row">${btn('Aplicar enlace','apply-image-url','type="button"','secondary small')}${btn('Quitar imagen','remove-image','type="button"','secondary small')}</div><p class="image-status small" role="status"></p></div>`;}
function editSchool(id){const s=admin.schools.find(s=>s.id===id)||{id:'',name:'',description:'',icon:'◇',order:admin.schools.length,image:'',updated:''};$('#admin-content').innerHTML=`<div class="panel editor-width"><h2>${s.id?'Editar escuela':'Crear escuela'}</h2><form id="school-form" data-id="${esc(s.id)}" data-updated="${esc(s.updated)}">${field('schoolName','Nombre de la escuela',s.name,'text','required maxlength="80"')}${textField('schoolDescription','Descripción',s.description,'maxlength="1000"')}<div class="form-grid">${field('schoolIcon','Símbolo (opcional)',s.icon,'text','maxlength="4"')}${field('schoolOrder','Orden en el campus',s.order,'number','required min="0" max="999"')}</div>${imageEditor(s.image)}<p class="error" role="alert"></p><div class="dialog-actions"><button class="btn" type="submit">Guardar escuela</button>${btn('Cancelar','cancel-editor','type="button"','secondary')}</div></form></div>`;}
async function compressCover(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>8*1024*1024)throw Error('Selecciona JPG, PNG o WebP de hasta 8 MB.');const url=URL.createObjectURL(file);try{const img=new Image();img.src=url;await img.decode();if(!img.width||!img.height)throw Error('Imagen inválida.');for(const width of [640,480,360,240]){const canvas=document.createElement('canvas');canvas.width=width;canvas.height=Math.round(width*9/16);const ctx=canvas.getContext('2d');ctx.fillStyle='#ffffff';ctx.fillRect(0,0,canvas.width,canvas.height);const scale=Math.min(canvas.width/img.width,canvas.height/img.height),w=img.width*scale,h=img.height*scale;ctx.drawImage(img,(canvas.width-w)/2,(canvas.height-h)/2,w,h);for(const quality of [.8,.6,.4]){const data=canvas.toDataURL('image/jpeg',quality);if(data.length<=16000)return data;}}throw Error('No pudimos reducir esta imagen. Prueba una imagen más sencilla o un enlace HTTPS.');}finally{URL.revokeObjectURL(url);}}
document.addEventListener('change',async event=>{if(!event.target.matches('.image-file'))return;const f=event.target.closest('form'),file=event.target.files[0];if(!file)return;const status=f.querySelector('.image-status');f.dataset.uploading='true';status.textContent='Preparando imagen…';try{const value=await compressCover(file);if(!f.isConnected)return;f.elements.image.value=value;f.querySelector('.image-url').value='';f.querySelector('.image-preview').innerHTML=coverImage(value,'Vista previa de portada');status.textContent='Imagen preparada. Pulsa Guardar para aplicar el cambio.';}catch(e){status.textContent=e.message;}finally{f.dataset.uploading='false';}});
document.addEventListener('error',event=>{if(event.target.matches?.('img.cover-image')){event.target.style.display='none';event.target.parentElement.classList.add('image-unavailable');}},true);

function assignmentsAdmin(){return `<div class="section-head"><h2>Asignación de cursos</h2></div><p class="muted">Selecciona quién puede acceder a cada curso. Quitar una asignación conserva el historial y los certificados.</p>${table(['Curso creado','Estado','Usuarios asignados','Acciones'],admin.courses.map(c=>[esc(c.title),tag(c.published?'Publicado':'Borrador'),(c.assignedUserIds||[]).length,btn('Añadir usuarios','assign-users',`data-id="${esc(c.id)}"`,'secondary small')]))}`;}
function editAssignments(id){const c=admin.courses.find(c=>c.id===id);if(!c)return;adminTab='asignaciones';const ids=c.assignedUserIds||[];$('#admin-content').innerHTML=`<div class="panel"><h2>Usuarios de ${esc(c.title)}</h2><p>Marca los usuarios que deben ver este curso. Desmarca para retirar su acceso. Los borradores solo estarán disponibles al publicarlos.</p><input id="assignment-search" type="search" placeholder="Buscar por nombre, correo, documento o área" aria-label="Buscar usuarios"><form id="assignment-form" data-id="${esc(c.id)}" data-revision="${esc(c.assignmentRevision||'')}"><div class="assignment-list">${admin.users.map(u=>`<label class="assignment-user" data-search="${esc([u.name,u.email,u.document,u.area].join(' ').toLowerCase())}"><input type="checkbox" name="userIds" value="${esc(u.id)}" ${ids.includes(u.id)?'checked':''} ${u.active===false&&!ids.includes(u.id)?'disabled':''}><span><strong>${esc(u.name||'Perfil pendiente')}</strong><br>${esc(u.email)} · ${esc(u.area||'Sin área')}${u.active===false?' · Inactivo':''}</span></label>`).join('')||'<p>No hay usuarios registrados. Autoriza sus correos en Personas y pídeles ingresar una vez.</p>'}</div><p class="error" role="alert"></p><div class="dialog-actions"><button class="btn">Guardar asignaciones</button>${btn('Cancelar','cancel-editor','type="button"','secondary')}</div></form></div>`;}
function completedCourses(){if(!me)return requireLogin();const done=me.attempts.filter(a=>a.passed);return heading('MI HISTORIAL','Cursos completados','Tus aprobaciones se conservan aunque un curso se retire del catálogo.')+(done.length?table(['Curso','Fecha de aprobación','Nota'],done.map(a=>[esc(a.courseTitle||a.courseId),date(a.date),a.score+'%'])):empty('Todavía no has completado cursos.','Aquí aparecerán los cursos que apruebes.'));}
document.addEventListener('input',e=>{if(e.target.id==='assignment-search'){const q=e.target.value.toLowerCase().trim();document.querySelectorAll('.assignment-user').forEach(n=>n.hidden=!n.dataset.search.includes(q));}});
